# Battlefield modpack updater - single file, portable.
# Run it from anywhere (Downloads, Desktop, wherever). First run asks which folder your
# modpack lives in (the "minecraft" folder inside your PrismLauncher instance - the one
# that contains "mods", "config", "saves") and remembers it for next time in
# %APPDATA%\BattlefieldUpdater\settings.json. Only downloads what actually changed.

Add-Type -AssemblyName System.Windows.Forms

$PackUrl = "https://raw.githubusercontent.com/Glesooo/battlefield-modpack/main/pack.toml"
$SettingsDir = Join-Path $env:APPDATA "BattlefieldUpdater"
$SettingsFile = Join-Path $SettingsDir "settings.json"

function Get-InstancePath {
    if (Test-Path $SettingsFile) {
        try {
            $saved = (Get-Content $SettingsFile -Raw | ConvertFrom-Json).InstancePath
            if ($saved -and (Test-Path $saved)) { return $saved }
            Write-Host "Сохранённая папка сборки больше не существует, выбери заново." -ForegroundColor Yellow
        } catch {
            Write-Host "Не удалось прочитать сохранённые настройки, выбери папку заново." -ForegroundColor Yellow
        }
    }

    [System.Windows.Forms.MessageBox]::Show(
        "Выбери папку 'minecraft' сборки Battlefield (в ней лежат папки mods, config, saves).`n`nОбычно это что-то вроде:`nPrismLauncher\instances\<Имя сборки>\minecraft",
        "Battlefield Updater", "OK", "Information") | Out-Null

    $dialog = New-Object System.Windows.Forms.FolderBrowserDialog
    $dialog.Description = "Папка 'minecraft' сборки Battlefield (с mods/config/saves)"
    $dialog.ShowNewFolderButton = $false
    if ($dialog.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) {
        Write-Host "Папка не выбрана, выхожу." -ForegroundColor Red
        Read-Host "Enter, чтобы закрыть"
        exit 1
    }
    $picked = $dialog.SelectedPath

    New-Item -ItemType Directory -Path $SettingsDir -Force | Out-Null
    @{ InstancePath = $picked } | ConvertTo-Json | Set-Content -LiteralPath $SettingsFile
    return $picked
}

$instancePath = Get-InstancePath
Write-Host "Папка сборки: $instancePath"
Set-Location -LiteralPath $instancePath

if (-not (Get-Command java -ErrorAction SilentlyContinue)) {
    Write-Host "Java не найдена на этом компьютере. Установи Java (она и так нужна для Minecraft) и запусти апдейтер снова." -ForegroundColor Red
    Read-Host "Enter, чтобы закрыть"
    exit 1
}

# The bootstrapper is embedded as base64 right in this script (not via ps2exe -embedFiles -
# that extracts at a fixed point before Set-Location runs, so its target can't depend on the
# instance folder the player just picked). Writing it out ourselves, after Set-Location,
# guarantees it lands next to the instance's own mods/config/saves - the layout
# packwiz-installer-bootstrap actually expects, matching the "drop it in your minecraft
# folder" usage the packwiz project itself documents.
$BootstrapB64 = ""
$bootstrapPath = Join-Path $instancePath "battlefield-installer-bootstrap.jar"
[System.IO.File]::WriteAllBytes($bootstrapPath, [System.Convert]::FromBase64String($BootstrapB64))

Write-Host "Проверка обновлений..."
& java -jar $bootstrapPath $PackUrl
$exitCode = $LASTEXITCODE

Write-Host ""
if ($exitCode -eq 0) {
    Write-Host "Готово - всё актуально." -ForegroundColor Green
} else {
    Write-Host "Апдейтер сообщил о проблеме (код $exitCode) - прокрути вверх, там подробности." -ForegroundColor Yellow
}
Read-Host "Enter, чтобы закрыть"
